mapper.select:
SELECT t_sprinkler.*,
t_rma_sprinkler.*
FROM t_rma_sprinkler
LEFT JOIN t_sprinkler ON t_sprinkler.sprinkler_id = t_rma_sprinkler.sprinkler_id

    t_rma_sprinkler.deleted_flag = #{queryForm.deletedFlag}

        AND INSTR(t_sprinkler.sprinkler_serial,#{queryForm.sprinklerSerial})


        AND INSTR(t_sprinkler.history,#{queryForm.history})


        AND INSTR(t_sprinkler.sprinkler_detail,#{queryForm.sprinklerDetail})


        AND t_sprinkler.disabled_flag = #{queryForm.disabledFlag}



        AND DATE_FORMAT(t_rma_sprinkler.ret_maintainence_date, '%Y-%m-%d') >= #{joinForm.retMaintainenceDateStartTime}


        AND DATE_FORMAT(t_rma_sprinkler.ret_maintainence_date, '%Y-%m-%d') <= #{joinForm.retMaintainenceDateEndTime}



        AND INSTR(t_rma_sprinkler.ret_maintainence_reason,#{joinForm.retMaintainenceReason})


        AND DATE_FORMAT(t_rma_sprinkler.ret_warehouse_date, '%Y-%m-%d') >= #{joinForm.retWarehouseDateStartTime}


        AND DATE_FORMAT(t_rma_sprinkler.ret_warehouse_date, '%Y-%m-%d') <= #{joinForm.retWarehouseDateEndTime}


        AND INSTR(t_rma_sprinkler.customer,#{joinForm.customer})


        AND INSTR(t_rma_sprinkler.rma_position,#{joinForm.rmaPosition})


        AND INSTR(t_rma_sprinkler.warehouse_check,#{joinForm.warehouseCheck})


        ORDER BY t_rma_sprinkler.ret_warehouse_date DESC

